CREATE TABLE employees (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, employment VARCHAR(20) NOT NULL, hourly_rate DECIMAL(16,2) NOT NULL, bsb VARCHAR(7) NOT NULL, account VARCHAR(9) NOT NULL);
CREATE TABLE timesheets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), starts TIMESTAMP NOT NULL, ends TIMESTAMP NOT NULL, public_holiday BOOLEAN NOT NULL);
CREATE TABLE pay_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, state VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE payslips (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES pay_runs(id), employee_id BIGINT NOT NULL REFERENCES employees(id), gross DECIMAL(16,2) NOT NULL, tax DECIMAL(16,2) NOT NULL, net DECIMAL(16,2) NOT NULL);
